-- Einzelprüfung vom 17.11.2026. Neue Entwurfsfassungen; kein UPDATE bestehender Inhalte.
BEGIN;
CREATE TEMP TABLE catalog_content_audit_install (
  template_key text PRIMARY KEY,
  previous_version integer NOT NULL,
  previous_hash text NOT NULL,
  definition jsonb NOT NULL
) ON COMMIT DROP;


LOCK TABLE public.central_document_catalog IN SHARE ROW EXCLUSIVE MODE;
DO $catalog_content_audit$
BEGIN
  IF to_regclass('public.central_document_catalog_version_history') IS NULL THEN
    RAISE EXCEPTION 'Vor dem Inhaltsabgleich muss die Versionshistorie des Vorlagenkatalogs eingerichtet sein.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM catalog_content_audit_install incoming
    WHERE NOT EXISTS (
      SELECT 1 FROM public.central_document_catalog existing
      WHERE existing.template_key = incoming.template_key AND existing.version = incoming.previous_version + 1
        AND existing.definition_json = incoming.definition AND existing.review_status = 'draft'
    )
    AND (
      NOT EXISTS (
        SELECT 1 FROM public.central_document_catalog predecessor
        WHERE predecessor.template_key = incoming.template_key AND predecessor.version = incoming.previous_version
          AND md5(predecessor.definition_json::text) = incoming.previous_hash AND predecessor.review_status = 'draft'
      )
      OR EXISTS (
        SELECT 1 FROM public.central_document_catalog newer
        WHERE newer.template_key = incoming.template_key AND newer.version > incoming.previous_version
      )
    )
  ) THEN
    RAISE EXCEPTION 'Mindestens eine Vorlagenfassung weicht von der geprüften Ausgangsversion ab.';
  END IF;
END
$catalog_content_audit$;

SELECT template_key, previous_version + 1, definition->>'title', definition->>'categoryKey',
       definition->>'target', definition->>'sourceMode', 'draft', definition
FROM catalog_content_audit_install
ON CONFLICT (template_key,version) DO NOTHING;

COMMIT;
