('csdc_qm_010',2,'fff66f6a3ef017ad3194c46c48d51e74','{"key":"csdc_qm_010","categoryKey":"qm","categoryName":"Qualitätsmanagement und Betriebsorganisation","title":"Dokumentenlenkung und Versionsübersicht","version":3,"modules":["office","pflege","stationaer","assist"],"target":"company","sourceMode":"create","layout":"table","orientation":"landscape","fields":[{"key":"date","label":"Dokumentdatum","type":"date","required":true},{"key":"author","label":"Verantwortliche Person","type":"text","required":true},{"key":"companyName","label":"Unternehmen / Vertragspartner","type":"text","required":true,"sourcePath":"company.name"},{"key":"companyAddress","label":"Unternehmensanschrift","type":"multiline","required":true,"sourcePath":"company.address"},{"key":"subjectName","label":"Organisation / Standort","type":"text","required":true,"sourcePath":"subject.name"},{"key":"subjectAddress","label":"Anschrift der zugeordneten Person / Organisation","type":"multiline","required":false,"sourcePath":"subject.address"},{"key":"f0_geltungsbereich_der_dokumentenlenkung","label":"Geltungsbereich der Dokumentenlenkung","type":"multiline","required":true},{"key":"f1_verantwortliche_stelle","label":"Verantwortliche Stelle","type":"multiline","required":false},{"key":"f2_regeln_zur_verteilung_und_ablage","label":"Regeln zur Verteilung und Ablage","type":"multiline","required":false}],"columns":["Dokument-ID","Bezeichnung","Version","Freigabe","Gültig ab","Ablösebezug","Verantwortlich"],"reviewStatus":"draft","legalReviewRequired":false,"clinicalReviewRequired":false,"sections":[{"key":"cs_process","heading":"CareSuite-Verfahren und Nachweis","text":"Der zentrale Office-Katalog dient als gemeinsame Vorlagenquelle der Module. Vorlage, konkrete Dokumentfassung und Datei-Prüfwert werden auseinandergehalten. Freigabe, Ausgabe, Zuordnung, Nachfolgefassung und lokale Änderungen erhalten einen geregelten Ablauf. Die neue geschützte Datenbankablage ist bis zum tatsächlichen Betriebsnachweis als n